// src/payments/charge.ts
export async function charge(req: Request, db: Db) {
  const key = req.headers.get('Idempotency-Key');
  const saved = key ? await db.idempotency.find(key) : null;
  if (saved) return saved.response;
  const response = await stripe.charges.create(await req.json());
  if (key) await db.idempotency.insert({ key, response });
  return response;
}

